import sympy
from sympy import MatrixBase, eye, zeros, Rational, Integer
from sympy.abc import x, y, z

# Standard linear algebra objects for potential witness expressions
I2 = eye(2)
I3 = eye(3)
O2 = zeros(2, 2)
O3 = zeros(3, 3)

def conditions(witness):
    """
    Checks whether the witness satisfies the hypotheses and falsifies the conclusion.
    """
    # H_1: R is a commutative ring with identity
    try:
        if hasattr(witness, '__iter__'):
            # Assume the ring R is generated by the elements of the matrix.
            # Check if all elements are commutative.
            h1 = all(getattr(elem, 'is_commutative', True) for elem in witness)
        else:
            h1 = False
    except Exception:
        h1 = False

    # H_2: M_n(R) is the ring of n \times n matrices over R
    try:
        # This implies the witness must be a square matrix.
        h2 = getattr(witness, 'is_square', False)
    except Exception:
        h2 = False

    # ¬Q: The conclusion fails (A is a unit in M_n(R) is NOT equivalent to det(A) is a unit in R)
    try:
        if not h2:
            neg_q = False
        else:
            elements = list(witness)
            
            # Determine the nature of the ring R from the matrix elements
            is_Z = all(isinstance(e, (int, Integer)) or (hasattr(e, 'is_Integer') and e.is_Integer) for e in elements)
            is_Q = all(isinstance(e, (int, Integer, Rational)) or (hasattr(e, 'is_Rational') and e.is_Rational) for e in elements)
            
            # 1. Check if A is a unit in M_n(R)
            try:
                A_inv = witness.inv()
                if is_Z:
                    A_is_unit = all(isinstance(e, (int, Integer)) or (hasattr(e, 'is_Integer') and e.is_Integer) for e in A_inv)
                elif is_Q:
                    A_is_unit = True
                else:
                    # Heuristic for general rings: the inverse elements should not introduce new types (like Pow for denominators)
                    types_in_witness = set(type(e) for e in elements)
                    allowed_types = types_in_witness.union({Integer, type(sympy.S.One), type(sympy.S.NegativeOne), type(sympy.S.Zero)})
                    A_is_unit = all(type(e) in allowed_types for e in A_inv)
            except Exception:
                A_is_unit = False

            # 2. Check if det(A) is a unit in R
            try:
                det_A = witness.det()
                if det_A == 1 or det_A == -1:
                    det_is_unit = True
                elif is_Z:
                    det_is_unit = False
                elif is_Q:
                    det_is_unit = (det_A != 0)
                else:
                    inv_det = 1 / det_A
                    types_in_witness = set(type(e) for e in elements)
                    allowed_types = types_in_witness.union({Integer, type(sympy.S.One), type(sympy.S.NegativeOne), type(sympy.S.Zero)})
                    det_is_unit = type(inv_det) in allowed_types
            except Exception:
                det_is_unit = False

            # The conclusion states they are equivalent. The negation means they differ.
            neg_q = (A_is_unit != det_is_unit)
    except Exception:
        neg_q = False

    return [bool(h1), bool(h2), bool(neg_q)]

CONDITION_LABELS = [
    "H_1: R is a commutative ring with identity",
    "H_2: M_n(R) is the ring of n \\times n matrices over R",
    "¬Q: (A is a unit in M_n(R)) is not equivalent to (det(A) is a unit in R)"
]

N_HYP = 2
NEG_Q_INDEX = 2